import { Injectable } from '@nestjs/common';
import {
    ValidationArguments,
    ValidationOptions,
    registerDecorator,
    ValidatorConstraint,
    ValidatorConstraintInterface,
} from 'class-validator';
import { CreateDimensionDto, DimensionTier, overageAllowedEnum } from './create-dimension.dto.js';

/**
 * The value which can be used on the last tier of a dimension to indicate that the tier is unbounded.
 */
export const UNBOUNDED_TIER = 'inf';

/**
 * The maximum amount of decimal places supported on any price field.
 */
export const MAX_PRICE_DECIMAL_PLACES = 8;

const isNumericString = (value: unknown): boolean => {
    if (typeof value !== 'string') {
        return false;
    }
    if (value.trim() === '') {
        return false;
    }
    return !isNaN(Number(value)) && !isNaN(parseFloat(value));
};

const isIntegerString = (value: unknown): boolean => isNumericString(value) && Number.isInteger(Number(value));

const decimalPlaces = (value: string): number => value.split('.')[1]?.length ?? 0;

/**
 * Sorts the tiers of a dimension by their numeric `tierPosition`.
 * The array which is passed in is never mutated, a new sorted array is always returned.
 */
export const sortTiersByPosition = (tiers: DimensionTier[]): DimensionTier[] =>
    [...tiers].sort((first, second) => Number(first?.tierPosition) - Number(second?.tierPosition));

/**
 * Validates the `tiers` field of a dimension.
 * All of the problems which are found with the tiers are returned as human readable messages,
 * an empty array means the tiers are valid.
 *
 * The rules which are enforced are the following:
 * - Tiers must be a non empty array of tier objects.
 * - `tierPosition` must be a unique integer numeric string.
 * - `upperBound` must be a positive numeric string, or the string `"inf"` which is only allowed on the last tier.
 * - The bounds of the tiers must increase, so they never overlap each other.
 * - Every bound must be a multiple of the `usageIncrement` of the dimension.
 * - `unitPrice` must be a positive numeric string with at most 8 decimal places.
 * - `unitPrice` is required on every tier except the first one, an omitted first price is a free tier.
 * - Tiers cannot be combined with `usageEntitlement`, `consumptionPrice` or `overageAllowed: true`.
 */
export const validateTiers = (
    tiers: DimensionTier[],
    dimension?: Partial<CreateDimensionDto> & Record<string, unknown>,
): string[] => {
    const errors: string[] = [];
    if (!Array.isArray(tiers)) {
        return ['tiers: The tiers field must be an array of tier objects'];
    }
    if (!tiers.length) {
        return ['tiers: At least one tier must be provided when the tiers field is set'];
    }
    if (tiers.some((tier) => !tier || typeof tier !== 'object' || Array.isArray(tier))) {
        return ['tiers: Every tier must be an object containing the fields tierPosition and upperBound'];
    }

    // Mutually exclusive fields
    const { usageEntitlement, consumptionPrice, overageAllowed, usageIncrement } = dimension ?? {};
    if (usageEntitlement !== undefined && usageEntitlement !== null) {
        errors.push('tiers: A dimension with tiers cannot also set usageEntitlement');
    }
    if (consumptionPrice !== undefined && consumptionPrice !== null) {
        errors.push('tiers: A dimension with tiers cannot also set consumptionPrice, prices are set per tier');
    }
    if (overageAllowed === overageAllowedEnum.true || (overageAllowed as unknown) === true) {
        errors.push('tiers: A dimension with tiers cannot also set overageAllowed to true');
    }

    // Positions
    tiers.forEach((tier) => {
        if (!isIntegerString(tier?.tierPosition)) {
            errors.push(
                `tiers: tierPosition ${tier?.tierPosition} is not valid, tierPosition must be a numeric string integer`,
            );
        }
    });
    const positions = tiers.map((tier) => Number(tier?.tierPosition));
    if (new Set(positions).size !== positions.length) {
        errors.push('tiers: Every tier must have a unique tierPosition');
    }

    const usageIncrementValue = usageIncrement !== undefined && usageIncrement !== null ? Number(usageIncrement) : NaN;
    const sortedTiers = sortTiersByPosition(tiers);
    let previousBound: number = 0;
    sortedTiers.forEach((tier, index) => {
        const { upperBound, unitPrice } = tier;
        const isLastTier = index === sortedTiers.length - 1;
        // Bounds
        if (upperBound === UNBOUNDED_TIER) {
            if (!isLastTier) {
                errors.push(
                    `tiers: An upperBound of "${UNBOUNDED_TIER}" is only allowed on the tier with the highest tierPosition`,
                );
            }
            previousBound = Infinity;
        } else if (!isNumericString(upperBound)) {
            errors.push(
                `tiers: upperBound ${upperBound} is not valid, upperBound must be a numeric string or the string "${UNBOUNDED_TIER}"`,
            );
        } else {
            const boundValue = parseFloat(upperBound);
            if (boundValue <= 0) {
                errors.push(`tiers: upperBound ${upperBound} must be greater than 0`);
            }
            if (boundValue <= previousBound) {
                errors.push(
                    `tiers: upperBound ${upperBound} must be greater than the upperBound of the previous tier, tier bounds cannot overlap`,
                );
            }
            if (!isNaN(usageIncrementValue) && usageIncrementValue > 0 && boundValue % usageIncrementValue !== 0) {
                errors.push(
                    `tiers: upperBound ${upperBound} must be a multiple of the usageIncrement ${usageIncrement} of the dimension`,
                );
            }
            previousBound = boundValue;
        }

        // Prices
        if (unitPrice === undefined || unitPrice === null) {
            if (index !== 0) {
                errors.push(
                    `tiers: unitPrice is required on every tier except the tier with the lowest tierPosition, tier ${tier?.tierPosition} is missing a unitPrice`,
                );
            }
            return;
        }
        if (!isNumericString(unitPrice)) {
            errors.push(`tiers: unitPrice ${unitPrice} is not valid, unitPrice must be a numeric string`);
            return;
        }
        if (parseFloat(unitPrice) < 0) {
            errors.push(`tiers: unitPrice ${unitPrice} cannot be negative`);
        }
        if (decimalPlaces(unitPrice) > MAX_PRICE_DECIMAL_PLACES) {
            errors.push(
                `tiers: unitPrice ${unitPrice} cannot have more than ${MAX_PRICE_DECIMAL_PLACES} digits of precision after the decimal place`,
            );
        }
    });

    return errors;
};

@ValidatorConstraint({ name: 'ValidateTiers', async: false })
@Injectable()
export class ValidateTiersRule implements ValidatorConstraintInterface {
    validate(tiers: DimensionTier[], args: ValidationArguments) {
        if (tiers === undefined || tiers === null) {
            return true;
        }
        return validateTiers(tiers, args?.object as CreateDimensionDto).length === 0;
    }

    defaultMessage(args: ValidationArguments) {
        const errors = validateTiers(args?.value as DimensionTier[], args?.object as CreateDimensionDto);
        return errors.join('. ');
    }
}

export function ValidateTiers(property: string, validationOptions?: ValidationOptions) {
    return function (object: unknown, propertyName: string) {
        registerDecorator({
            name: 'ValidateTiers',
            target: object.constructor,
            propertyName: propertyName,
            constraints: [property],
            options: validationOptions,
            validator: ValidateTiersRule,
        });
    };
}

