    /**
     * The tiers of a dimension are stored as a JSON string inside of the ledger,
     * this helper transforms the stored value back into the tier objects of the dimension.
     */
    private static parseTiers(tiers: string | DimensionTier[]): DimensionTier[] {
        if (!tiers) {
            return undefined;
        }
        if (Array.isArray(tiers)) {
            return tiers.length ? tiers : undefined;
        }
        try {
            const parsedTiers = JSON.parse(tiers);
            return Array.isArray(parsedTiers) && parsedTiers.length ? parsedTiers : undefined;
        } catch (e) {
            DimensionEntity.logger.error(`Failed to parse the tiers of a dimension: ${tiers}`);
            return undefined;
        }
    }
