/**
 * Determines the tiers of a dimension after an update has been applied to it.
 * Tiers are always replaced as a whole, passing `null` for the tiers removes them from the dimension.
 * <br><br>
 * Since the tiers of a dimension are mutually exclusive with the `usageEntitlement`, `consumptionPrice`
 * and `overageAllowed: true` fields, those fields are dropped from the dimension when tiers are set on it.
 * Introducing one of the mutually exclusive fields on a dimension which keeps its tiers is rejected.
 */
private mergeTiersForUpdate(
    currentDimension: ReadDimensionResponseData,
    updatedFields: Partial<UpdateDimensionDto>,
): Partial<CreateDimensionDto> {
    const tiersProvided = updatedFields?.tiers !== undefined;
    const tiers = tiersProvided ? updatedFields.tiers : currentDimension?.tiers;
    if (!tiers?.length) {
        // Either the dimension has no tiers, or the tiers of the dimension are being removed with a null value
        return { tiers: undefined };
    }
    const conflictingFields: string[] = [];
    if (updatedFields?.consumptionPrice !== undefined && updatedFields?.consumptionPrice !== null) {
        conflictingFields.push('consumptionPrice');
    }
    if (updatedFields?.usageEntitlement !== undefined && updatedFields?.usageEntitlement !== null) {
        conflictingFields.push('usageEntitlement');
    }
    if (updatedFields?.overageAllowed === overageAllowedEnum.true) {
        conflictingFields.push('overageAllowed');
    }
    if (conflictingFields.length) {
        throw new BadRequestException(
            `A dimension with tiers cannot also set ${conflictingFields.join(
                ', ',
            )}. Remove the tiers of the dimension by passing tiers: null in order to set ${conflictingFields.join(
                ', ',
            )}`,
        );
    }
    const usageIncrement =
        updatedFields?.usageIncrement !== undefined && updatedFields?.usageIncrement !== null
            ? updatedFields.usageIncrement
            : currentDimension?.usageIncrement;
    const errors = validateTiers(tiers, { usageIncrement });
    if (errors.length) {
        throw new BadRequestException(errors.join('. '));
    }
    return { tiers, consumptionPrice: undefined, usageEntitlement: undefined, overageAllowed: undefined };
}

