/**
 * Sorts the volume based pricing tiers of a dimension by their numeric `tierPosition`.
 * A new array is always returned, the tiers of the dimension are never mutated.
 */
public static sortTiers(tiers: DimensionTier[]): DimensionTier[] {
    if (!Array.isArray(tiers)) {
        return [];
    }
    return [...tiers].sort((first, second) => Number(first?.tierPosition) - Number(second?.tierPosition));
}

/**
 * Allocates the total usage of a dimension across the volume based pricing tiers of the dimension.
 * <br><br>
 * Tiers are processed in the ascending order of their `tierPosition`.
 * The `upperBound` of a tier is inclusive and the lower bound of a tier is the upper bound of the tier before it,
 * meaning the first tier starts at zero usage. A tier with an `upperBound` of `"inf"` is unbounded.
 * <br><br>
 * Every tier is returned, tiers which are not consumed by the usage have a usage of `0`.
 */
public static allocateUsageToTiers({
    totalUsage,
    tiers,
}: {
    totalUsage: number;
    tiers: DimensionTier[];
}): TieredUsageAllocation[] {
    const usage = Number(totalUsage);
    const totalUsageToAllocate = isNaN(usage) || usage < 0 ? 0 : usage;
    let lowerBound = 0;
    return Billing.sortTiers(tiers).map((tier) => {
        const upperBound = tier?.upperBound === 'inf' ? Infinity : parseFloat(tier?.upperBound);
        const usageInTier = Math.max(Math.min(totalUsageToAllocate, upperBound) - lowerBound, 0);
        const allocation: TieredUsageAllocation = {
            tier,
            lowerBound,
            upperBound,
            usage: usageInTier,
        };
        lowerBound = upperBound;
        return allocation;
    });
}

