/**
 * Determines the unit cost of a line item for a given price of a dimension.
 * The precision of the price is preserved, and the price is converted with the exchange rate of the invoice.
 */
static getUnitCostForPrice({ price, exchangeRate }: { price: string; exchangeRate: number }): number {
    const parsedPrice = parseFloat(price);
    return Number(
        (parsedPrice * exchangeRate).toFixed(
            Offering.getDecimalsForNumber(parsedPrice) === 0 ? 2 : Offering.getDecimalsForNumber(parsedPrice),
        ),
    );
}

/**
 * Adds the line items of a dimension which is billed with volume based pricing tiers.
 * <br><br>
 * The usage of the dimension is allocated across the tiers of the dimension,
 * and every tier which is consumed by the usage produces its own line item with the unit price of that tier.
 * When a tier has a `tierName`, the name of the tier is appended to the name of the line item.
 */
static addTieredLineItemsForUsage({
    dimension,
    totalUsage,
    exchangeRate,
    lineItems,
    negative,
    offeringInstance,
}: {
    dimension: ReadDimensionResponseData;
    totalUsage: number;
    exchangeRate: number;
    lineItems: InvoiceLineItems;
    negative?: boolean;
    offeringInstance: Offering;
}): InvoiceLineItems {
    const {
        dimensionId,
        dimensionName,
        tiers,
        usageIncrement,
        consumptionUnit: { unit, type },
    } = dimension;
    const allocations = Billing.allocateUsageToTiers({ totalUsage, tiers });
    allocations.forEach(({ tier, usage }) => {
        if (!usage || usage <= 0) {
            // Only tiers which are consumed by the usage appear on the invoice
            return;
        }
        // A missing unit price on the first tier is a free tier
        const unitCost = Offering.getUnitCostForPrice({
            price: tier?.unitPrice !== undefined && tier?.unitPrice !== null ? tier.unitPrice : '0',
            exchangeRate,
        });
        const shouldDisplayLineItem = Billing.determineIfLineItemShown({
            Offering: offeringInstance,
            dimension,
            totalUsage: usage,
            unitCost,
            freeDimensionOnInvoice: offeringInstance.settings?.freeDimensionOnInvoice,
        });
        if (!shouldDisplayLineItem) {
            return;
        }
        const { displayName, total: displayTotal } = InvoiceLineItem.prepareLineItem({
            total: usage,
            dimensionType: type,
            dimensionId,
            dimensionName,
            offeringName: offeringInstance.offeringName,
            usageIncrement: parseInt(usageIncrement),
            dimensionUnit: unit,
            negative,
        });
        lineItems.addLineItem(
            new InvoiceLineItem(
                tier?.tierName ? `${displayName} - ${tier.tierName}` : displayName,
                displayTotal,
                unitCost,
            ),
        );
    });
    return lineItems;
}

