import { plainToInstance } from 'class-transformer';
import { validate } from 'class-validator';
import { CreateDimensionDto, countBasedUnits, roundingEnum } from './create-dimension.dto.js';
import { UpdateDimensionDto } from './update-dimension.dto.js';
import { validateTiers } from './tiersValidator.js';
import { DimensionEntity, Numerical, numericalType } from '../entities/dimensions.entity.js';
import { SampleType, aggregationInterval, aggregationMethod } from './create-dimension.dto.js';

const baseDimension = {
    dimensionName: 'Request',
    consumptionUnit: { type: 'count', unit: countBasedUnits['count-based'] },
    usageIncrement: '1',
    rounding: roundingEnum.ceiling,
};

const tiers = [
    { tierPosition: '1', upperBound: '1000', tierName: 'First 1000', unitPrice: '0.05' },
    { tierPosition: '2', upperBound: 'inf', tierName: 'Everything else', unitPrice: '0.03' },
];

const validateDto = async (input: Record<string, unknown>, DtoClass = CreateDimensionDto) => {
    const dto = plainToInstance(DtoClass, input);
    const errors = await validate(dto as object);
    return errors.map((error) => Object.values(error.constraints ?? {}).join(' ')).join(' ');
};

describe('Dimension tiers', () => {
    describe('validation', () => {
        test('accepts a tiered dimension without a consumption price', async () => {
            expect(await validateDto({ ...baseDimension, tiers })).toEqual('');
        });
        test('accepts an omitted unit price on the first tier as a free tier', async () => {
            expect(
                await validateDto({
                    ...baseDimension,
                    tiers: [
                        { tierPosition: '1', upperBound: '1000' },
                        { tierPosition: '2', upperBound: 'inf', unitPrice: '0.03' },
                    ],
                }),
            ).toEqual('');
        });
        test('rejects a missing unit price on any tier after the first one', async () => {
            const errors = await validateDto({
                ...baseDimension,
                tiers: [
                    { tierPosition: '1', upperBound: '1000', unitPrice: '0.05' },
                    { tierPosition: '2', upperBound: 'inf' },
                ],
            });
            expect(errors).toContain('unitPrice is required');
        });
        test('rejects bounds which do not increase', async () => {
            const errors = await validateDto({
                ...baseDimension,
                tiers: [
                    { tierPosition: '1', upperBound: '1000', unitPrice: '0.05' },
                    { tierPosition: '2', upperBound: '1000', unitPrice: '0.03' },
                ],
            });
            expect(errors).toContain('cannot overlap');
        });
        test('rejects bounds which are not aligned to the usage increment', async () => {
            const errors = await validateDto({
                ...baseDimension,
                usageIncrement: '100',
                tiers: [
                    { tierPosition: '1', upperBound: '150', unitPrice: '0.05' },
                    { tierPosition: '2', upperBound: 'inf', unitPrice: '0.03' },
                ],
            });
            expect(errors).toContain('must be a multiple of the usageIncrement');
        });
        test('rejects an unbounded tier which is not the last tier', async () => {
            const errors = await validateDto({
                ...baseDimension,
                tiers: [
                    { tierPosition: '1', upperBound: 'inf', unitPrice: '0.05' },
                    { tierPosition: '2', upperBound: '1000', unitPrice: '0.03' },
                ],
            });
            expect(errors).toContain('only allowed on the tier with the highest tierPosition');
        });
        test('rejects duplicated tier positions', async () => {
            const errors = await validateDto({
                ...baseDimension,
                tiers: [
                    { tierPosition: '1', upperBound: '1000', unitPrice: '0.05' },
                    { tierPosition: '1', upperBound: 'inf', unitPrice: '0.03' },
                ],
            });
            expect(errors).toContain('unique tierPosition');
        });
        test.each([
            ['usageEntitlement', { usageEntitlement: 1000 }],
            ['consumptionPrice', { consumptionPrice: '0.05' }],
            ['overageAllowed', { usageEntitlement: 1000, overageAllowed: 'true' }],
        ])('rejects tiers combined with %s', async (field, conflicting) => {
            const errors = await validateDto({ ...baseDimension, ...conflicting, tiers });
            expect(errors).toContain(field);
        });
        test('allows the tiers to be removed with a null value on an update', async () => {
            expect(await validateDto({ tiers: null, consumptionPrice: '1' }, UpdateDimensionDto)).toEqual('');
        });
        test('validates the tiers against the usage increment of the dimension', () => {
            expect(validateTiers(tiers, { usageIncrement: '1' })).toEqual([]);
            expect(validateTiers(tiers, { usageIncrement: '3' })).toEqual([
                'tiers: upperBound 1000 must be a multiple of the usageIncrement 3 of the dimension',
            ]);
        });
    });

    describe('persistence', () => {
        test('tiers survive a round trip through the ledger model', () => {
            const numerical = new Numerical({
                numericalType: numericalType.int,
                dimensionUnit: countBasedUnits['count-based'],
                dimensionUnitType: 'count',
                aggregationInterval: aggregationInterval.hour,
                aggregationMethod: aggregationMethod.sum,
                priceSegments: [{ lowerLimit: '0', upperLimit: 'inf' }],
                sampleType: SampleType.gauge,
                usageIncrement: 1,
                rounding: roundingEnum.ceiling,
                tiers,
            });
            const point = Numerical.transformer(numerical, {
                tags: {},
                tag(name: string, value: string) {
                    this.tags[name] = value;
                    return this;
                },
                // eslint-disable-next-line @typescript-eslint/ban-ts-comment
                //@ts-ignore
            } as unknown as Parameters<typeof Numerical.transformer>[1]);
            // eslint-disable-next-line @typescript-eslint/ban-ts-comment
            //@ts-ignore
            const dbModel = point.tags;
            expect(JSON.parse(dbModel.tiers)).toEqual(tiers);

            const entity = Numerical.dbModelToEntity(dbModel);
            expect(entity.tiers).toEqual(tiers);

            const readDto = new CreateDimensionDto({
                numerical: entity,
                typeofDimension: 'numerical',
                dimensionName: 'Request',
                // eslint-disable-next-line @typescript-eslint/ban-ts-comment
                //@ts-ignore
            } as DimensionEntity);
            expect(readDto.tiers).toEqual(tiers);
            expect(readDto.consumptionPrice).toBeUndefined();
        });
        test('dimensions without tiers are unchanged', () => {
            const numerical = Numerical.dbModelToEntity({
                numericalType: numericalType.int,
                dimensionUnit: countBasedUnits['count-based'],
                dimensionUnitType: 'count',
                aggregationInterval: aggregationInterval.hour,
                aggregationMethod: aggregationMethod.sum,
                priceSegments: JSON.stringify([{ lowerLimit: '0', upperLimit: 'inf', price: '0.4' }]),
                sampleType: SampleType.gauge,
                usageIncrement: '1',
                rounding: roundingEnum.ceiling,
            });
            expect(numerical.tiers).toBeUndefined();
            const readDto = new CreateDimensionDto({
                numerical,
                typeofDimension: 'numerical',
                dimensionName: 'Request',
                // eslint-disable-next-line @typescript-eslint/ban-ts-comment
                //@ts-ignore
            } as DimensionEntity);
            expect(readDto.tiers).toBeUndefined();
            expect(readDto.consumptionPrice).toEqual('0.4');
        });
    });
});

