                    data: [
                        {
                            dimensionId,
                            usage: usageValues.map((value) => ({
                                startTime: new Date().toISOString(),
                                endTime: new Date().toISOString(),
                                value,
                            })),
                        },
                    ],
                }) as ReadCustomerUsageData,
        );
        const offeringInstance = Offering.getInstance(
            { ...usageBasedOffering, dimensions: [dimension] },
            fakeCustomerID,
            fakeBusinessID,
            invoicesService,
            fakeSettings,
            schedulerService,
            customerService,
        );
        const lineItems = await Offering.getLineItemsForUsage({
            customerService,
            customer: { ...customer, currency },
            startDate: new Date('2023-08-01T00:00:00.000Z'),
            endDate: new Date('2023-08-31T23:59:59.999Z'),
            customerId: fakeCustomerID,
            dimensions: [dimension],
            businessID: fakeBusinessID,
            lineItems: new InvoiceLineItems(),
            offeringInstance,
        });
        return lineItems.getLineItems();
    };

    describe('allocateUsageToTiers', () => {
        test('allocates usage across the inclusive bounds of the tiers, ordered by tier position', () => {
            const tiers = [
                { tierPosition: '2', upperBound: '2000', unitPrice: '0.03' },
                { tierPosition: '10', upperBound: 'inf', unitPrice: '0.01' },
                { tierPosition: '1', upperBound: '1000', unitPrice: '0.05' },
            ];
            expect(Billing.allocateUsageToTiers({ totalUsage: 2500, tiers })).toEqual([
                { tier: tiers[2], lowerBound: 0, upperBound: 1000, usage: 1000 },
                { tier: tiers[0], lowerBound: 1000, upperBound: 2000, usage: 1000 },
                { tier: tiers[1], lowerBound: 2000, upperBound: Infinity, usage: 500 },
            ]);
        });
        test('the upper bound of a tier is inclusive', () => {
            const tiers = [
                { tierPosition: '1', upperBound: '1000', unitPrice: '0.05' },
                { tierPosition: '2', upperBound: 'inf', unitPrice: '0.01' },
            ];
            expect(Billing.allocateUsageToTiers({ totalUsage: 1000, tiers }).map(({ usage }) => usage)).toEqual([
                1000, 0,
            ]);
            expect(Billing.allocateUsageToTiers({ totalUsage: 1001, tiers }).map(({ usage }) => usage)).toEqual([
                1000, 1,
            ]);
            expect(Billing.allocateUsageToTiers({ totalUsage: 0, tiers }).map(({ usage }) => usage)).toEqual([0, 0]);
        });
    });

    test('creates a line item per consumed tier', async () => {
        const lineItems = await getLineItems({ dimension: tieredDimension(), usageValues: ['2500'] });
        expect(lineItems).toEqual([
            expect.objectContaining(new InvoiceLineItem('Request - foobar - First 1000', 1000, 0.05)),
            expect.objectContaining(new InvoiceLineItem('Request - foobar - Next 1000', 1000, 0.03)),
            expect.objectContaining(new InvoiceLineItem('Request - foobar - Everything else', 500, 0.01)),
        ]);
    });
    test('does not create line items for tiers which are not consumed', async () => {
        const lineItems = await getLineItems({ dimension: tieredDimension(), usageValues: ['500'] });
        expect(lineItems).toEqual([
            expect.objectContaining(new InvoiceLineItem('Request - foobar - First 1000', 500, 0.05)),
        ]);
    });
    test('omits the tier name from the line item name when it is not set', async () => {
        const lineItems = await getLineItems({
            dimension: tieredDimension({
                tiers: [
                    { tierPosition: '1', upperBound: '1000', unitPrice: '0.05' },
                    { tierPosition: '2', upperBound: 'inf', unitPrice: '0.01' },
                ],
            }),
            usageValues: ['1500'],
        });
        expect(lineItems).toEqual([
            expect.objectContaining(new InvoiceLineItem('Request - foobar', 1000, 0.05)),
            expect.objectContaining(new InvoiceLineItem('Request - foobar', 500, 0.01)),
        ]);
    });
    test('divides the quantity of every tier by the usage increment', async () => {
        const lineItems = await getLineItems({
            dimension: tieredDimension({
                usageIncrement: '1000',
                tiers: [
                    { tierPosition: '1', upperBound: '1000000', tierName: 'First million', unitPrice: '2' },
                    { tierPosition: '2', upperBound: 'inf', tierName: 'Rest', unitPrice: '1' },
                ],
            }),
            usageValues: ['1500000'],
        });
        expect(lineItems).toEqual([
            expect.objectContaining(new InvoiceLineItem('Request - Thousand - foobar - First million', 1000, 2)),
            expect.objectContaining(new InvoiceLineItem('Request - Thousand - foobar - Rest', 500, 1)),
        ]);
    });
    test('an omitted unit price on the first tier is a free tier', async () => {
        const lineItems = await getLineItems({
            dimension: tieredDimension({
                tiers: [
                    { tierPosition: '1', upperBound: '1000', tierName: 'Free' },
                    { tierPosition: '2', upperBound: 'inf', tierName: 'Paid', unitPrice: '0.05' },
                ],
            }),
            usageValues: ['1500'],
        });
        expect(lineItems).toEqual([
            expect.objectContaining(new InvoiceLineItem('Request - foobar - Free', 1000, 0)),
            expect.objectContaining(new InvoiceLineItem('Request - foobar - Paid', 500, 0.05)),
        ]);
    });
    test('preserves the precision of the tier prices and converts the currency', async () => {
        const lineItems = await getLineItems({
            dimension: tieredDimension({
                tiers: [
                    { tierPosition: '1', upperBound: '1000', unitPrice: '1.23456789' },
                    { tierPosition: '2', upperBound: 'inf', unitPrice: '1' },
                ],
            }),
            usageValues: ['1500'],
            currency: SupportedCurrencies.EUR,
        });
        expect(lineItems).toEqual([
            // 1.12345678 = 0.91 * 1.23456789, the exchange rate is mocked to 0.91
            expect.objectContaining(new InvoiceLineItem('Request - foobar', 1000, 1.12345678)),
            expect.objectContaining(new InvoiceLineItem('Request - foobar', 500, 0.91)),
        ]);
    });
    test('non tiered dimensions keep producing a single line item', async () => {
        const lineItems = await getLineItems({
            dimension: tieredDimension({ tiers: undefined, consumptionPrice: '0.4' }),
            usageValues: ['1500'],
        });
        expect(lineItems).toEqual([expect.objectContaining(new InvoiceLineItem('Request - foobar', 1500, 0.4))]);
    });
});

import { Test, TestingModule } from '@nestjs/testing';
import { createMock } from '@golevelup/ts-jest';
import { BadRequestException } from '@nestjs/common';
import { DimensionsService } from './dimensions.service.js';
import { InfluxService } from '../influx/influx.service.js';
import { countBasedUnits, roundingEnum } from './dto/create-dimension.dto.js';
import { ReadDimensionResponseData } from './dto/read-dimension.dto.js';

const tiers = [
    { tierPosition: '1', upperBound: '1000', tierName: 'First 1000', unitPrice: '0.05' },
    { tierPosition: '2', upperBound: 'inf', tierName: 'Everything else', unitPrice: '0.03' },
];

const dimensionId = 'fake-dimension-id';
const businessID = 'fake-business-id';

const baseDimension = {
    dimensionName: 'Request',
    consumptionUnit: { type: 'count' as const, unit: countBasedUnits['count-based'] },
    usageIncrement: '1',
    rounding: roundingEnum.ceiling,
};

type FakePoint = {
    tags: Record<string, string>;
    fields: Record<string, string>;
    tag: (name: string, value: string) => FakePoint;
    stringField: (name: string, value: string) => FakePoint;
};

const createFakePoint = (): FakePoint => {
    const point: FakePoint = {
        tags: {},
        fields: {},
        tag(name: string, value: string) {
            point.tags[name] = value;
            return point;
        },
        stringField(name: string, value: string) {
            point.fields[name] = value;
            return point;
        },
    };
    return point;
};

describe('DimensionsService tiers', () => {
    let service: DimensionsService;
    let influxService: InfluxService;
    let loadedPoints: FakePoint[];

    beforeEach(async () => {
        const module: TestingModule = await Test.createTestingModule({
            providers: [DimensionsService],
        })
            .useMocker(createMock)
            .compile();

        service = module.get<DimensionsService>(DimensionsService);
        influxService = module.get<InfluxService>(InfluxService);
        loadedPoints = [];
        //eslint-disable-next-line
        //@ts-ignore
        influxService.getPoint = jest.fn(() => createFakePoint());
        //eslint-disable-next-line
        //@ts-ignore
        influxService.loadPoints = jest.fn(async (bucket, org, points) => {
            loadedPoints.push(...(points as unknown as FakePoint[]));
        });
    });

    const persistedTiers = (): unknown => {
        const [point] = loadedPoints;
        return point.tags.tiers ? JSON.parse(point.tags.tiers) : undefined;
    };

    const mockStoredDimension = (dimension: Partial<ReadDimensionResponseData>) => {
        jest.spyOn(service, 'findOne').mockImplementation(async () => ({
            message: 'Found Dimension',
            data: [{ ...baseDimension, dimensionId, ...dimension } as ReadDimensionResponseData],
        }));
    };

    test('the tiers of a dimension are persisted on creation', async () => {
        await service.create({ ...baseDimension, businessID, tiers } as never, 'subject');
        expect(persistedTiers()).toEqual(tiers);
        expect(JSON.parse(loadedPoints[0].tags.priceSegments)[0].price).toBeUndefined();
    });

    test('a dimension without tiers does not persist any tiers', async () => {
        await service.create({ ...baseDimension, businessID, consumptionPrice: '0.4' } as never, 'subject');
        expect(persistedTiers()).toBeUndefined();
        expect(JSON.parse(loadedPoints[0].tags.priceSegments)[0].price).toEqual('0.4');
    });

    test('an update replaces the tiers of a dimension', async () => {
        mockStoredDimension({ tiers });
        const updatedTiers = [
            { tierPosition: '1', upperBound: '500', unitPrice: '0.07' },
            { tierPosition: '2', upperBound: 'inf', unitPrice: '0.01' },
        ];
        await service.update({ dimensionId, businessID, tiers: updatedTiers }, 'subject');
        expect(persistedTiers()).toEqual(updatedTiers);
    });

    test('an update with null tiers removes the tiers of a dimension', async () => {
        mockStoredDimension({ tiers });
        await service.update({ dimensionId, businessID, tiers: null, consumptionPrice: '0.4' }, 'subject');
        expect(persistedTiers()).toBeUndefined();
        expect(JSON.parse(loadedPoints[0].tags.priceSegments)[0].price).toEqual('0.4');
    });

    test('adding tiers to a priced dimension removes the mutually exclusive fields', async () => {
        mockStoredDimension({ consumptionPrice: '0.4' });
        await service.update({ dimensionId, businessID, tiers }, 'subject');
        expect(persistedTiers()).toEqual(tiers);
        expect(JSON.parse(loadedPoints[0].tags.priceSegments)[0].price).toBeUndefined();
        expect(loadedPoints[0].tags.usageEntitlement).toBeUndefined();
    });

    test('a consumption price cannot be set on a tiered dimension', async () => {
        mockStoredDimension({ tiers });
        await expect(service.update({ dimensionId, businessID, consumptionPrice: '0.4' }, 'subject')).rejects.toThrow(
            BadRequestException,
        );
    });

    test('the tiers are validated against the usage increment of the stored dimension', async () => {
        mockStoredDimension({ usageIncrement: '300' });
        await expect(service.update({ dimensionId, businessID, tiers }, 'subject')).rejects.toThrow(
            BadRequestException,
        );
    });
});

